-- 📚 꼭집 주거 사전 — 선정 절차 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 4.2초 · 결과:
-- {"anns": 146, "by_std": {"SH 고유": 2, "공공임대(6·10·50년)": 11, "국민임대": 41, "매입임대": 48, "영구임대": 20, "전세임대": 4, "통합공공임대": 4, "행복주택": 13, "행복주택(신혼희망)": 3}, "선착순": 0, "선착순_ex": null, "추첨": 88, "추첨_ex": ["20648_1_경기도_광명시", "20647_1_경기도_광명시", "2015122300020899"], "배점순": 58, "배점순_ex": ["SH_311349", "2015122300020899", "2015122300020893"], "선계약후검증": 0, "선계약후검증_ex": null, "서류제출대상자": 37, "서류제출대상자_ex": ["21390_부산광역시_사하구", "2015122300020899", "2015122300020895"], "자격검증": 57, "자격검증_ex": ["2015122300020899", "2015122300020898", "2015122300020895"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='선정 절차'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='선정 절차' group by 1)q),'선착순',(select count(distinct announcement_id) from y where cls='선정 절차' and t~'선착순'),'선착순_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='선정 절차' and t~'선착순' order by 1 desc limit 3)q),'추첨',(select count(distinct announcement_id) from y where cls='선정 절차' and t~'추첨'),'추첨_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='선정 절차' and t~'추첨' order by 1 desc limit 3)q),'배점순',(select count(distinct announcement_id) from y where cls='선정 절차' and t~'(배점|점수)[^.]{0,20}(순|높은)'),'배점순_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='선정 절차' and t~'(배점|점수)[^.]{0,20}(순|높은)' order by 1 desc limit 3)q),'선계약후검증',(select count(distinct announcement_id) from y where cls='선정 절차' and t~'선\s*계약\s*후\s*검증'),'선계약후검증_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='선정 절차' and t~'선\s*계약\s*후\s*검증' order by 1 desc limit 3)q),'서류제출대상자',(select count(distinct announcement_id) from y where cls='선정 절차' and t~'서류\s*제출\s*대상자'),'서류제출대상자_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='선정 절차' and t~'서류\s*제출\s*대상자' order by 1 desc limit 3)q),'자격검증',(select count(distinct announcement_id) from y where cls='선정 절차' and t~'(자격\s*검증|소득[^.]{0,10}자산\s*조회)'),'자격검증_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='선정 절차' and t~'(자격\s*검증|소득[^.]{0,10}자산\s*조회)' order by 1 desc limit 3)q))j;
